#include "frontend/mac/MacFrontEnd.h"

#include "app/ApplicationController.h"
#include "dictation/DictationSession.h"
#include "frontend/mac/SpeecherBridge.h"
#include "ui/TranscriberPopup.h"

// Generated by swiftc from src/frontend/mac/swift, which is why the Swift target
// has to build before this one.
#import "SpeecherUI-Swift.h"

#include <QApplication>
#include <QDesktopServices>
#include <QUrl>
#include <QWidget>

namespace speecher {
namespace {

// The Qt front end wires its own dictation popup in its constructor and offers
// no way to decline one. On macOS the panel is SwiftUI's, so the Qt popup comes
// straight back out of the session's signal path rather than showing itself
// beside it. The opt-out belongs in QtFrontEnd; this stands in until it is there.
void detachQtDictationPopup(DictationSession *session)
{
    for (QWidget *widget : QApplication::allWidgets()) {
        auto *popup = qobject_cast<TranscriberPopup *>(widget);
        if (!popup) {
            continue;
        }
        QObject::disconnect(session, nullptr, popup, nullptr);
        popup->hide();
    }
}

} // namespace

struct MacFrontEnd::Native {
    SpeecherBridge *bridge = nil;
    SpeecherMacUI *ui = nil;
};

MacFrontEnd::MacFrontEnd(ApplicationController *controller)
    : m_controller(controller)
    , m_qt(controller)
    , m_native(std::make_unique<Native>())
{
    detachQtDictationPopup(controller->session());
    m_native->bridge = [[SpeecherBridge alloc] initWithController:controller];
    // The schema names the commands an Action row offers; what they do belongs
    // to the front end, as it does on Qt.
    m_native->bridge.settingsSchema.actionTriggered = ^(NSString *rowId) {
        const QString id = QString::fromNSString(rowId);
        if (id == QStringLiteral("runSetup")) {
            controller->showSetupAssistant();
            return;
        }
        if (id == QStringLiteral("openReleases")) {
            QDesktopServices::openUrl(
                QUrl(QStringLiteral("https://github.com/firemonster612/speecher/releases")));
        }
    };
    // The menu bar extra is the app's front door, so it exists from launch
    // rather than waiting for someone to ask for a window.
    m_native->ui = [[SpeecherMacUI alloc] initWithBridge:m_native->bridge];
}

MacFrontEnd::~MacFrontEnd() = default;

// One window: the settings are all a Mac app puts in a window of its own, and
// dictation itself lives in the menu bar and the floating panel.
void MacFrontEnd::showMainWindow()
{
    [m_native->ui showSettings];
    // frontEndReady defers its work by a turn of the event loop, which is what
    // lets the window this call just ordered front draw first.
    m_controller->frontEndReady();
}

void MacFrontEnd::showSettingsWindow()
{
    showMainWindow();
}

void MacFrontEnd::showSetupAssistant()
{
    m_qt.showSetupAssistant();
}

bool MacFrontEnd::captureMainWindow(const QString &path)
{
    return [m_native->ui captureSettingsToPath:path.toNSString()];
}

void MacFrontEnd::showDictationError(const QString &message)
{
    [m_native->ui showDictationProblem:message.toNSString()];
}

void MacFrontEnd::alert()
{
    QApplication::beep();
}

} // namespace speecher
